input.command:
cd ~/measurement_env/hera/models/tetralayer_fs_count && menv python - <<'EOF' 2>&1 | tail -40
import sys; sys.path.insert(0,'.')
import fs_count_b0 as m
import numpy as np
print([n for n in dir(m) if not n.startswith('_')][:60])
for n in [1.0,1.5,2.0,2.5,3.0,3.2,-1.0,-1.2]:
    try:
        EF, orbs = m.abab_fs(n); ms = m.abab_mstar(n)
        ab = m.abca_fs(n); am = m.abca_mstar(n)
        FL = 2.0678e-15/ (4*1.602e-19)*0  # placeholder
        print(f"n={n:+.1f}: ABAB F={[round(F,2) for F,k in orbs]} m*={[round(mm,3) for F,mm in ms]} | ABCA F_total={ab[4]:.2f} topo={ab[1]} ncomp={ab[2]} m*={am[1]:.3f}")
    except Exception as e: print(n, 'ERR', e)
EOF

